commands.command:
/usr/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createTransferWorkspace, createProgressFeed, collectProgressTelemetry } from './src/workspace.js';
const deferred = () => { let resolve; const promise = new Promise(r => resolve = r); return {promise, resolve}; };
const old = deferred(), newer = deferred();
const feed = createProgressFeed({ initialPacket: 'initial', decode: p => p === 'old' ? old.promise : p === 'new' ? newer.promise : p });
const history = [], display = [], queue = [], telemetry = [];
const workspace = createTransferWorkspace({ transport() {}, onCancel() {}, record: x => queue.push(x), showQueued() {}, recordProgress: x => history.push(x.frame), showProgress: x => display.push(x.frame) });
const file = {id: 'a', progressFeed: feed};
workspace.select(file);
assert.deepEqual([history, display], [['initial'], ['initial']]);
feed.emit('old'); feed.emit('new'); newer.resolve('new'); await Promise.resolve(); old.resolve('old'); await Promise.resolve();
assert.deepEqual(history, ['initial', 'new', 'old']);
assert.deepEqual(display, ['initial', 'new']);
workspace.hide();
feed.emit('hidden');
assert.deepEqual(history, ['initial', 'new', 'old']);
workspace.select(file);
assert.deepEqual(display, ['initial', 'new', 'initial']);
workspace.retry();
assert.deepEqual(display, ['initial', 'new', 'initial', 'initial']);
assert.deepEqual(queue.map(x => x.kind), ['select', 'select', 'retry']);
const stop = collectProgressTelemetry(feed, x => telemetry.push(x));
feed.emit('delta'); stop();
assert.deepEqual(telemetry, ['delta']);
workspace.dispose();
console.log('progress scenarios passed');
EOF"

/usr/bin/bash -lc "node --check src/progress.js
node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createTransferWorkspace, createProgressFeed } from './src/workspace.js';
let workspace;
const displayed = [], recorded = [];
const feed = createProgressFeed({initialPacket: 'initial'});
workspace = createTransferWorkspace({transport() {}, onCancel() {}, record() {}, showQueued() {}, recordProgress(x) { recorded.push(x.frame); if (x.frame === 'initial') workspace.hide(); }, showProgress(x) { displayed.push(x.frame); }});
workspace.select({id:'a', progressFeed:feed});
feed.emit('later');
assert.deepEqual(recorded, ['initial']);
assert.deepEqual(displayed, []);
assert.equal(workspace.snapshot().visitId, null);
workspace.dispose();
console.log('reentrant close passed');
EOF"

